 int score(){int s=100;float x=temp();if(x>=43)s-=20;else if(x>=40)s-=10;if(ram()>90)s-=8;if(free()<20)s-=8;if(!shOk())s-=4;return Math.max(0,s);}Intent bi(){return registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));}int level(){Intent i=bi();return i==null?-1:i.getIntExtra(BatteryManager.EXTRA_LEVEL,-1);}float temp(){Intent i=bi();return i==null?0:i.getIntExtra(BatteryManager.EXTRA_TEMPERATURE,0)/10f;}String tempName(float x){return x>=43?"Mycket varm":x>=40?"Varm":x>=35?"Normal/varm":"Normal";}int ram(){ActivityManager a=(ActivityManager)getSystemService(ACTIVITY_SERVICE);ActivityManager.MemoryInfo m=new ActivityManager.MemoryInfo();a.getMemoryInfo(m);return(int)((m.totalMem-m.availMem)*100/m.totalMem);}long free(){return new StatFs(getFilesDir().getPath()).getAvailableBytes()/1073741824L;}
