 void debloat(){base("🛡️ SMART DEBLOAT 4.0","Beskrivning • risk • status • batch • failsafe",true);note(shStatus());btn("✨ Rekommenderad S23 Ultra-debloat",()->recommended());for(String[]a:PK)if(installed(a[1])){sec(a[0]+" • "+a[2]);note(a[3]+"\n"+a[1]+"\nStatus: "+(enabled(a[1])?"✅ Aktiv":"⛔ Avaktiverad"));if(enabled(a[1]))btn("Avaktivera "+a[0],()->disableAsk(a));else btn("Återställ "+a[0],()->pm("pm enable --user 0 "+a[1],a[1],false));}sec("Återställning");btn("Återställ allt Toolbox avaktiverat",()->restoreAll());}
