 void pm(String cmd,String pkg,boolean dis){if(!shOk()){requestSh();return;}new Thread(()->{try{Method m=Shizuku.class.getDeclaredMethod("newProcess",String[].class,String[].class,String.class);m.setAccessible(true);java.lang.Process q=(java.lang.Process)m.invoke(null,new Object[]{new String[]{"sh","-c",cmd},null,null});int c=q.waitFor();runOnUiThread(()->{if(c==0){Set<String>s=new HashSet<>(p.getStringSet("disabled",new HashSet<>()));if(dis)s.add(pkg);else s.remove(pkg);p.edit().putStringSet("disabled",s).apply();toast("Klart");log((dis?"Avaktiverade ":"Återställde ")+pkg);}else toast("Misslyckades: "+c);});}catch(Throwable e){runOnUiThread(()->toast("Shizuku-kommandot misslyckades"));}}).start();}void restoreAll(){for(String x:new HashSet<>(p.getStringSet("disabled",new HashSet<>())))pm("pm enable --user 0 "+x,x,false);}void restoreFail(){for(String x:p.getStringSet("failsafe",new HashSet<>()))if(installed(x)&&!enabled(x))pm("pm enable --user 0 "+x,x,false);}
 void inspector(){base("📦 APP INSPECTOR 2.0","Sök installerad app eller paket-ID",true);EditText e=new EditText(this);e.setHint("Sök app eller paket…");e.setTextColor(Color.WHITE);e.setHintTextColor(Color.GRAY);root.addView(e);btn("Sök installerade appar",()->appList(e.getText().toString()));btn("Inspektera exakt paket-ID",()->inspect(e.getText().toString().trim()));}void appList(String q){PackageManager pm=getPackageManager();List<ApplicationInfo>all=pm.getInstalledApplications(0);ArrayList<ApplicationInfo>m=new ArrayList<>();String z=q.toLowerCase();for(ApplicationInfo a:all){String l=""+pm.getApplicationLabel(a);if(z.isEmpty()||l.toLowerCase().contains(z)||a.packageName.toLowerCase().contains(z))m.add(a);}m.sort((a,b)->(""+pm.getApplicationLabel(a)).compareToIgnoreCase(""+pm.getApplicationLabel(b)));int n=Math.min(120,m.size());String[]s=new String[n];for(int i=0;i<n;i++)s[i]=pm.getApplicationLabel(m.get(i))+"\n"+m.get(i).packageName;new AlertDialog.Builder(this).setTitle("Installerade appar: "+m.size()).setItems(s,(d,i)->inspect(m.get(i).packageName)).setNegativeButton("Stäng",null).show();}void inspect(String x){try{PackageManager pm=getPackageManager();ApplicationInfo a=pm.getApplicationInfo(x,0);PackageInfo i=pm.getPackageInfo(x,0);new AlertDialog.Builder(this).setTitle(""+pm.getApplicationLabel(a)).setMessage("Paket: "+x+"\nVersion: "+i.versionName+"\nVersion code: "+i.getLongVersionCode()+"\nTyp: "+(((a.flags&ApplicationInfo.FLAG_SYSTEM)!=0)?"Systemapp":"Användarapp")+"\nStatus: "+(a.enabled?"Aktiv":"Avaktiverad")).setNeutralButton("Appinfo",(d,w)->startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+x)))).setPositiveButton("OK",null).show();}catch(Exception e){toast("Paketet hittades inte");}}
 void thermalPage(){base("🌡️ THERMAL WATCH 2.0","Min • max • medel • flera testlängder",true);float[]s=stats();note("Aktuellt: "+temp()+"°C • "+tempName(temp()));sec("Historikstatistik");note(s[3]>0?"Min "+s[0]+"°C • Max "+s[1]+"°C • Medel "+String.format(Locale.ROOT,"%.1f",s[2])+"°C • "+(int)s[3]+" mätningar":"Ingen historik");btn("Starta 60 sek",()->startThermal(12));btn("Starta 5 min",()->startThermal(60));btn("Starta 15 min",()->startThermal(180));sec("Senaste");note(p.getString("temps","Ingen historik"));btn("Rensa historik",()->{p.edit().remove("temps").apply();thermalPage();});}void startThermal(int n){samples=0;target=n;thermal=new Runnable(){public void run(){saveTemp(temp());samples++;if(samples<target)h.postDelayed(this,5000);else{thermal=null;toast("Thermal Watch klar");thermalPage();}}};h.post(thermal);}void stopThermal(){if(thermal!=null){h.removeCallbacks(thermal);thermal=null;}}void saveTemp(float x){String now=new SimpleDateFormat("MM-dd HH:mm:ss",Locale.getDefault()).format(new Date());String old=p.getString("temps","");String n=now+" • "+x+"°C"+(old.isEmpty()?"":"\n"+old);String[]a=n.split("\n");StringBuilder b=new StringBuilder();for(int i=0;i<Math.min(180,a.length);i++)b.append(a[i]).append(i<Math.min(180,a.length)-1?"\n":"");p.edit().putString("temps",b.toString()).apply();}float[]stats(){float mi=999,ma=-999,sum=0;int n=0;for(String l:p.getString("temps","").split("\n"))try{int a=l.indexOf("• ")+2,b=l.indexOf("°C");float x=Float.parseFloat(l.substring(a,b));mi=Math.min(mi,x);ma=Math.max(ma,x);sum+=x;n++;}catch(Exception e){}return n==0?new float[]{0,0,0,0}:new float[]{mi,ma,sum/n,n};}
 void benchmark(){base("⚙️ CPU BENCHMARK","Kort säkert beräkningstest • ingen överklockning",true);note("Kör inte om telefonen redan är mycket varm.");btn("Starta benchmark",()->runBench());String s=p.getString("bench","");if(!s.isEmpty()){sec("Senaste resultat");note(s);}}void runBench(){float before=temp();if(before>=43){toast("Telefonen är för varm");return;}new Thread(()->{long st=System.nanoTime();double z=0;for(int i=1;i<=10000000;i++)z+=Math.sqrt(i)*Math.sin(i*.001);long ms=(System.nanoTime()-st)/1000000;float after=temp();String r="Tid: "+ms+" ms\nTemperatur: "+before+" → "+after+"°C\nÖkning: "+String.format(Locale.ROOT,"%.1f",after-before)+"°C";p.edit().putString("bench",r).apply();log("Benchmark "+ms+" ms");runOnUiThread(()->{toast("Benchmark klar");benchmark();});}).start();}
 void battery(){base("🔋 BATTERY LAB","Livevärden från Androids batterisensor",true);Intent i=bi();BatteryManager bm=(BatteryManager)getSystemService(BATTERY_SERVICE);int mv=i==null?0:i.getIntExtra(BatteryManager.EXTRA_VOLTAGE,0),plug=i==null?0:i.getIntExtra(BatteryManager.EXTRA_PLUGGED,0);long ua=bm.getLongProperty(BatteryManager.BATTERY_PROPERTY_CURRENT_NOW);double v=mv/1000.0,a=Math.abs(ua)/1000000.0,w=v*a;note("Batteri: "+level()+"%\nTemperatur: "+temp()+"°C\nSpänning: "+String.format(Locale.ROOT,"%.3f",v)+" V\nStröm: "+String.format(Locale.ROOT,"%.0f",ua/1000.0)+" mA\nUppskattad momentan effekt: "+String.format(Locale.ROOT,"%.2f",w)+" W\nAnsluten: "+(plug==0?"Nej":"Ja"));note("Effekten är en sensoruppskattning, inte laddarens märkta watt.");btn("Uppdatera",()->battery());}
