 boolean writeOk(){if(Settings.System.canWrite(this))return true;startActivity(new Intent(Settings.ACTION_MANAGE_WRITE_SETTINGS,Uri.parse("package:"+getPackageName())));return false;}boolean shInstalled(){try{getPackageManager().getPackageInfo("moe.shizuku.privileged.api",0);return true;}catch(Exception e){return false;}}boolean shAlive(){try{return Shizuku.pingBinder();}catch(Throwable e){return false;}}boolean shOk(){try{return shAlive()&&Shizuku.checkSelfPermission()==PackageManager.PERMISSION_GRANTED;}catch(Throwable e){return false;}}String shStatus(){if(!shInstalled())return"❌ Shizuku ej installerad";if(!shAlive())return"⚠️ Shizuku-tjänsten är inte igång";return shOk()?"✅ Shizuku aktiv och behörig":"🟡 Behörighet krävs";}void requestSh(){try{if(!shAlive()){openPkg("moe.shizuku.privileged.api");return;}Shizuku.requestPermission(REQ);}catch(Throwable e){toast("Kunde inte begära behörighet");}}boolean installed(String x){try{getPackageManager().getPackageInfo(x,0);return true;}catch(Exception e){return false;}}boolean enabled(String x){try{return getPackageManager().getApplicationInfo(x,0).enabled;}catch(Exception e){return false;}}void log(String s){String old=p.getString("history","");String n=new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.getDefault()).format(new Date())+" • "+s+(old.isEmpty()?"":"\n"+old);p.edit().putString("history",n).apply();}void open(String a){try{startActivity(new Intent(a));}catch(Exception e){}}boolean openPkg(String x){Intent i=getPackageManager().getLaunchIntentForPackage(x);if(i!=null){startActivity(i);return true;}return false;}void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
